From internal/core/src/exec/operator/search-groupby/SearchGroupByOperator.h lines 380-396:

    bool Push(const CompositeGroupKey& key) {
        auto [it, inserted] = group_map_.try_emplace(key, 0);
        if (inserted) {
            if (static_cast<int>(group_map_.size()) > group_capacity_) {
                group_map_.erase(it);
                return false;
            }
        }
        if (it->second >= group_size_) {
            return false;
        }
        it->second += 1;
        if (it->second >= group_size_) {
            enough_group_count_ += 1;
        }
        return true;
    }

